<script setup lang="ts">
import { computed, ref, toRef } from 'vue';
import type { ExchangeItemVue3, LegacyQslVue3 } from '../contracts';
import { useAdminList } from './use-admin-list';
import { useAdminFilters } from './memory';
import AdminFeedback from './AdminFeedback.vue';
import AdminPager from './AdminPager.vue';
import AdminCardImages from './AdminCardImages.vue';
import Dialog from '../components/Dialog.vue';
import Card3DViewer from '../components/Card3DViewer.vue';
import ExchangeContactLogs from '../components/ExchangeContactLogs.vue';
const props = defineProps<{ qsl: LegacyQslVue3 }>();
const state = useAdminFilters('/api/admin/exchanges',{status:''});
const status = toRef(state.filters,'status'), filters = computed(() => ({status:status.value}));
const { data, loading, error, load } = useAdminList<ExchangeItemVue3>(props.qsl, '/api/admin/exchanges', filters, 12);
const selected = ref<ExchangeItemVue3>();
const parties = computed(() => selected.value ? [
  { label:'申请人 · 发出申请', user:selected.value.fromUser, address:selected.value.fromAddress },
  { label:'接收人 · 卡片所有者', user:selected.value.toUser, address:selected.value.toAddress },
] : []);
</script>
<template><div class="a-tab-body"><div class="toolbar a-toolbar"><h2>{{ qsl.t('换卡记录') }}</h2><label>{{ qsl.t('状态') }}<select v-model="status" class="select"><option value="">{{ qsl.t('全部状态') }}</option><option v-for="s in ['pending','approved','rejected','completed','cancelled']" :key="s" :value="s">{{ qsl.exchangeText(s) }}</option></select></label></div><AdminFeedback :loading="loading" :error="error" :empty="!data?.items.length" :t="qsl.t" @retry="load()" /><div v-if="data && data.items.length && !loading && !error" class="table-wrap a-table-wrap"><table class="table a-table a-exchanges-table"><thead><tr><th>{{ qsl.t('卡片') }}</th><th>{{ qsl.t('申请人') }}</th><th>{{ qsl.t('接收人') }}</th><th>{{ qsl.t('状态') }}</th><th>{{ qsl.t('提交时间') }}</th><th>{{ qsl.t('操作') }}</th></tr></thead><tbody><tr v-for="item in data.items" :key="item.id"><td>{{ item.card?.title || qsl.t('卡片已删除') }}</td><td>{{ item.fromUser?.displayName || item.fromUser?.username || qsl.t('用户已删除') }}</td><td>{{ item.toUser?.displayName || item.toUser?.username || qsl.t('用户已删除') }}</td><td>{{ qsl.exchangeText(item.status) }}</td><td>{{ qsl.formatDateTime(item.createdAt) }}</td><td><button type="button" class="btn btn-ghost btn-sm" @click="selected = item">{{ qsl.t('查看详情') }}</button></td></tr></tbody></table></div><AdminPager v-if="data" :page="data" :busy="loading" :t="qsl.t" @go="load" />
<Dialog v-if="selected" :title="qsl.t('换卡申请详情')" :t="qsl.t" size="lg" @close="selected = undefined"><div class="a-exch-detail"><div class="a-exch-preview"><Card3DViewer v-if="selected.card" :front="selected.card.frontImage" :back="selected.card.backImage" :ratio="selected.card.ratio || { w:3,h:2 }" :create="qsl.card3d.create" :options="{width:236,autoRotate:false}"><template #fallback><AdminCardImages :card="selected.card" :qsl="qsl" /></template></Card3DViewer><h3>{{ selected.card?.title || qsl.t('卡片已删除') }}</h3><a v-if="selected.card?.id" :href="'/card/' + encodeURIComponent(selected.card.id)" data-link>{{ qsl.t('查看卡片详情') }}</a></div><div class="a-exch-info"><div class="a-exch-statusrow"><b>{{ selected.id }}</b><span>{{ qsl.exchangeText(selected.status) }}</span><span>{{ qsl.formatDateTime(selected.createdAt) }}</span></div><section class="a-info-block"><h4>{{ qsl.t('申请留言') }}</h4><blockquote class="a-quote">{{ selected.message || '—' }}</blockquote><p v-if="selected.rejectReason" class="a-quote a-quote--danger">{{ selected.rejectReason }}</p></section><ExchangeContactLogs :logs="selected.selectedContactLogs" :t="qsl.t" /><section v-if="selected.preferredCardTitle" class="a-info-block"><h4>{{ qsl.t('对方希望收到的卡片') }}</h4><a v-if="selected.preferredCard?.id" :href="'/card/' + encodeURIComponent(selected.preferredCard.id)" data-link>{{ selected.preferredCardTitle }}</a><p v-else>{{ selected.preferredCardTitle }}</p></section><div class="a-parties"><section v-for="party in parties" :key="party.label" class="a-party"><h4>{{ qsl.t(party.label) }}</h4><b>{{ party.user?.displayName || party.user?.username || qsl.t('用户已删除') }}</b><div v-if="party.address" class="a-addr-lines"><b>{{ party.address.name }} · {{ party.address.phone }}</b><span>{{ [party.address.province,party.address.city,party.address.line1].filter(Boolean).join(' ') }}</span><span>{{ party.address.country }} {{ party.address.postalCode }}</span></div><p v-else>{{ qsl.t('暂无地址信息') }}</p></section></div><section class="a-info-block"><h4>{{ qsl.t('时间线') }}</h4><p>{{ qsl.t('提交换卡申请') }} · {{ qsl.formatDateTime(selected.createdAt) }}</p><p v-if="selected.decidedAt">{{ qsl.exchangeText(selected.status) }} · {{ qsl.formatDateTime(selected.decidedAt) }}</p><p v-if="selected.status === 'completed'">{{ qsl.t('交换完成') }} · {{ qsl.formatDateTime(selected.updatedAt || null) }}</p></section><p class="info-banner">{{ qsl.t('管理员视角为只读：换卡状态由参与双方操作，管理员无法直接修改。') }}</p></div></div></Dialog></div></template>
